public class SubLine_intersection_TriageGen4Test {

    private static final double EPSILON = 1e-10;









    @Test
    public void testIntersection_OutsideOne_IncludeEndPointsTrue() {
        // Line 1: (0,0) to (1,1)
        SubLine subLine1 = new SubLine(new Vector2D(0, 0), new Vector2D(1, 1));
        // Line 2: (2,0) to (0,2)
        SubLine subLine2 = new SubLine(new Vector2D(2, 0), new Vector2D(0, 2));

        // Intersection is at (1,1). 
        // For subLine1, (1,1) is an endpoint (NOT OUTSIDE).
        // For subLine2, (1,1) is INSIDE (NOT OUTSIDE).
        // However, let's force one to be OUTSIDE.

        // Line 1: (0,0) to (0.5, 0.5)
        SubLine subLine1_small = new SubLine(new Vector2D(0, 0), new Vector2D(0.5, 0.5));
        // Line 2: (0,2) to (2,0) -> intersection (1,1)

        Vector2D result = subLine1_small.intersection(subLine2, true);

        Assert.assertNull(result);
    }




}

